1	package httpapi
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"net/http"
8		"time"
9	
10		"github.com/jackc/pgx/v5"
11		"github.com/jackc/pgx/v5/pgconn"
12		"github.com/jackc/pgx/v5/pgxpool"
13	)
14	
15	// errNotFound signals that a referenced row does not exist for the tenant.
16	var errNotFound = errors.New("not found")
17	
18	const schemaSQL = `
19	CREATE TABLE IF NOT EXISTS quota_pools (
20	    tenant_id   text        NOT NULL,
21	    pool_id     text        NOT NULL,
22	    lim         bigint      NOT NULL CHECK (lim > 0),
23	    valid_from  timestamptz NOT NULL,
24	    valid_until timestamptz NOT NULL,
25	    created_at  timestamptz NOT NULL DEFAULT now(),
26	    PRIMARY KEY (tenant_id, pool_id),
27	    CHECK (valid_from < valid_until)
28	);
29	
30	CREATE TABLE IF NOT EXISTS reservations (
31	    tenant_id      text        NOT NULL,
32	    pool_id        text        NOT NULL,
33	    reservation_id text        NOT NULL,
34	    amount         bigint      NOT NULL CHECK (amount > 0),
35	    status         text        NOT NULL CHECK (status IN ('pending', 'confirmed', 'released', 'expired')),
36	    expires_at     timestamptz NOT NULL,
37	    created_at     timestamptz NOT NULL DEFAULT now(),
38	    updated_at     timestamptz NOT NULL DEFAULT now(),
39	    PRIMARY KEY (tenant_id, pool_id, reservation_id),
40	    FOREIGN KEY (tenant_id, pool_id) REFERENCES quota_pools (tenant_id, pool_id)
41	);
42	
43	CREATE INDEX IF NOT EXISTS reservations_active_idx
44	    ON reservations (tenant_id, pool_id, expires_at)
45	    WHERE status IN ('pending', 'confirmed');
46	
47	CREATE TABLE IF NOT EXISTS idempotency_records (
48	    id              bigserial    PRIMARY KEY,
49	    tenant_id       text         NOT NULL,
50	    operation       text         NOT NULL,
51	    idempotency_key text         NOT NULL,
52	    request_hash    text         NOT NULL,
53	    status_code     integer      NOT NULL,
54	    response_body   bytea        NOT NULL,
55	    created_at      timestamptz NOT NULL DEFAULT now(),
56	    UNIQUE (tenant_id, idempotency_key)
57	);
58	`
59	
60	// EnsureSchema creates the required tables and indexes if they are absent.
61	// It also pins every pooled connection to UTC so RFC3339 timestamps are
62	// rendered consistently regardless of the database server's timezone.
63	func EnsureSchema(ctx context.Context, pool *pgxpool.Pool) error {
64		pool.Config().ConnConfig.RuntimeParams["timezone"] = "UTC"
65		if _, err := pool.Exec(ctx, schemaSQL); err != nil {
66			return err
67		}
68		return nil
69	}
70	
71	type pgStore struct {
72		pool *pgxpool.Pool
73	}
74	
75	// NewStore wraps a pgx connection pool as the API backend.
76	func NewStore(pool *pgxpool.Pool) backend {
77		return &pgStore{pool: pool}
78	}
79	
80	func (s *pgStore) Ping(ctx context.Context) error {
81		return s.pool.Ping(ctx)
82	}
83	
84	func (s *pgStore) createPool(ctx context.Context, tenantID, poolID string, in poolInput) (poolResponse, bool, error) {
85		var resp poolResponse
86		err := s.pool.QueryRow(ctx, `
87			INSERT INTO quota_pools (tenant_id, pool_id, lim, valid_from, valid_until)
88			VALUES ($1, $2, $3, $4, $5)
89			ON CONFLICT (tenant_id, pool_id) DO NOTHING
90			RETURNING tenant_id, pool_id, lim, valid_from, valid_until, created_at`,
91			tenantID, poolID, in.limit, in.validFrom, in.validUntil,
92		).Scan(&resp.TenantID, &resp.PoolID, &resp.Limit, &resp.ValidFrom, &resp.ValidUntil, &resp.CreatedAt)
93		if errors.Is(err, pgx.ErrNoRows) {
94			return poolResponse{}, false, nil
95		}
96		if err != nil {
97			return poolResponse{}, false, err
98		}
99		resp.normalize()
100		return resp, true, nil
101	}
102	
103	// idempotencyOutcome is the resolution of the idempotency record race.
104	type idempotencyOutcome int
105	
106	const (
107		idempotencyClaimed  idempotencyOutcome = iota // this transaction owns the record and must run business logic
108		idempotencyReplay                             // a completed record exists with the same request hash
109		idempotencyMismatch                           // a record exists but carries a different request hash
110	)
111	
112	// claimIdempotency inserts or locks the tenant-scoped idempotency record.
113	// Idempotency scope is (tenant, key): the same key reused with different
114	// request content anywhere across the tenant's POST endpoints is a 409,
115	// while an identical replay returns 200 and the original result. The claim
116	// is resolved before any business validation, and concurrent same-key
117	// requests serialize on the row lock so the business logic runs at most
118	// once. Postgres makes a speculative insert wait for a competing
119	// transaction; ON CONFLICT DO NOTHING returns no rows only once the
120	// competitor committed, so a surviving row always exists for FOR UPDATE.
121	func claimIdempotency(ctx context.Context, tx pgx.Tx, tenantID, operation, key, requestHash string) (idempotencyOutcome, operationResult, error) {
122		var insertedID int64
123		err := tx.QueryRow(ctx, `
124			INSERT INTO idempotency_records
125			    (tenant_id, operation, idempotency_key, request_hash, status_code, response_body)
126			VALUES ($1, $2, $3, $4, 0, ''::bytea)
127			ON CONFLICT (tenant_id, idempotency_key) DO NOTHING
128			RETURNING id`,
129			tenantID, operation, key, requestHash,
130		).Scan(&insertedID)
131		if err == nil {
132			return idempotencyClaimed, operationResult{}, nil
133		}
134		if !errors.Is(err, pgx.ErrNoRows) {
135			return 0, operationResult{}, err
136		}
137	
138		var storedHash string
139		var storedBody []byte
140		err = tx.QueryRow(ctx, `
141			SELECT request_hash, response_body
142			FROM idempotency_records
143			WHERE tenant_id = $1 AND idempotency_key = $2
144			FOR UPDATE`,
145			tenantID, key,
146		).Scan(&storedHash, &storedBody)
147		if err != nil {
148			return 0, operationResult{}, err
149		}
150		if storedHash != requestHash {
151			return idempotencyMismatch, operationResult{
152				status: http.StatusConflict,
153				body:   mustJSON(errorResponse{Error: "Idempotency-Key was reused with a different request"}),
154			}, nil
155		}
156		// Same request replay: always surface as HTTP 200 with the original result.
157		return idempotencyReplay, operationResult{status: http.StatusOK, body: storedBody}, nil
158	}
159	
160	func completeIdempotency(ctx context.Context, tx pgx.Tx, tenantID, key string, result operationResult) error {
161		_, err := tx.Exec(ctx, `
162			UPDATE idempotency_records
163			SET status_code = $3, response_body = $4
164			WHERE tenant_id = $1 AND idempotency_key = $2`,
165			tenantID, key, result.status, result.body)
166		return err
167	}
168	
169	// conflictResult finalizes a claimed idempotency record with a 409 result
170	// and commits the transaction, making the conflict response itself replayable.
171	func conflictResult(ctx context.Context, tx pgx.Tx, tenantID, key, message string) (operationResult, error) {
172		result := operationResult{status: http.StatusConflict, body: mustJSON(errorResponse{Error: message})}
173		if err := completeIdempotency(ctx, tx, tenantID, key, result); err != nil {
174			return operationResult{}, err
175		}
176		if err := tx.Commit(ctx); err != nil {
177			return operationResult{}, err
178		}
179		return result, nil
180	}
181	
182	func mustJSON(v any) []byte {
183		body, err := json.Marshal(v)
184		if err != nil {
185			// All values marshalled here are plain structs with fixed fields.
186			panic(err)
187		}
188		return body
189	}
190	
191	func (r *reservationResponse) normalize() {
192		r.ExpiresAt = r.ExpiresAt.UTC()
193		r.CreatedAt = r.CreatedAt.UTC()
194		r.UpdatedAt = r.UpdatedAt.UTC()
195	}
196	
197	func (p *poolResponse) normalize() {
198		p.ValidFrom = p.ValidFrom.UTC()
199		p.ValidUntil = p.ValidUntil.UTC()
200		p.CreatedAt = p.CreatedAt.UTC()
201	}
202	
203	// expirePending moves past-deadline pending reservations of the pool to
204	// expired, releasing their reserved quota. Must run while the pool row lock
205	// is held so the availability check observes a stable reservation set.
206	func expirePending(ctx context.Context, tx pgx.Tx, tenantID, poolID string) error {
207		_, err := tx.Exec(ctx, `
208			UPDATE reservations
209			SET status = 'expired', updated_at = now()
210			WHERE tenant_id = $1 AND pool_id = $2 AND status = 'pending' AND expires_at <= now()`,
211			tenantID, poolID)
212		return err
213	}
214	
215	func (s *pgStore) createReservation(ctx context.Context, tenantID, poolID, key, requestHash string, in reservationInput) (operationResult, error) {
216		tx, err := s.pool.Begin(ctx)
217		if err != nil {
218			return operationResult{}, err
219		}
220		defer tx.Rollback(ctx)
221	
222		operation := "create_reservation:" + poolID
223		outcome, replay, err := claimIdempotency(ctx, tx, tenantID, operation, key, requestHash)
224		if err != nil {
225			return operationResult{}, err
226		}
227		if outcome != idempotencyClaimed {
228			if err := tx.Commit(ctx); err != nil {
229				return operationResult{}, err
230			}
231			return replay, nil
232		}
233		fail := func(message string) (operationResult, error) {
234			return conflictResult(ctx, tx, tenantID, key, message)
235		}
236	
237		// Lock the pool so concurrent reservations over the same pool serialize;
238		// the availability check and insert then happen atomically.
239		var poolLimit int64
240		var validFrom, validUntil time.Time
241		err = tx.QueryRow(ctx, `
242			SELECT lim, valid_from, valid_until
243			FROM quota_pools
244			WHERE tenant_id = $1 AND pool_id = $2
245			FOR UPDATE`,
246			tenantID, poolID,
247		).Scan(&poolLimit, &validFrom, &validUntil)
248		if errors.Is(err, pgx.ErrNoRows) {
249			return fail("quota pool not found")
250		}
251		if err != nil {
252			return operationResult{}, err
253		}
254	
255		// Lazy expiry: pending reservations past their deadline release quota.
256		if err := expirePending(ctx, tx, tenantID, poolID); err != nil {
257			return operationResult{}, err
258		}
259	
260		now := time.Now().UTC()
261		if validFrom.After(now) || !validUntil.After(now) {
262			return fail("quota pool is not currently valid")
263		}
264		if !in.expiresAt.After(now) || in.expiresAt.After(validUntil) {
265			return fail("expiresAt must be in the future and no later than the pool validity end")
266		}
267	
268		// Available quota is the limit minus the amounts of unexpired pending
269		// reservations and all confirmed reservations (confirmed quota is held
270		// permanently and is not released by pending expiry).
271		var reserved int64
272		err = tx.QueryRow(ctx, `
273			SELECT COALESCE(SUM(amount), 0)
274			FROM reservations
275			WHERE tenant_id = $1 AND pool_id = $2 AND (
276			    status = 'confirmed'
277			    OR (status = 'pending' AND expires_at > now())
278			)`,
279			tenantID, poolID,
280		).Scan(&reserved)
281		if err != nil {
282			return operationResult{}, err
283		}
284		if poolLimit-reserved < in.amount {
285			return fail("insufficient quota available")
286		}
287	
288		resp := reservationResponse{
289			TenantID:      tenantID,
290			PoolID:        poolID,
291			ReservationID: in.reservationID,
292			Amount:        in.amount,
293			Status:        "pending",
294			ExpiresAt:     in.expiresAt,
295		}
296		err = tx.QueryRow(ctx, `
297			INSERT INTO reservations (tenant_id, pool_id, reservation_id, amount, status, expires_at)
298			VALUES ($1, $2, $3, $4, 'pending', $5)
299			RETURNING created_at, updated_at`,
300			tenantID, poolID, in.reservationID, in.amount, in.expiresAt,
301		).Scan(&resp.CreatedAt, &resp.UpdatedAt)
302		if err != nil {
303			var pgErr *pgconn.PgError
304			if errors.As(err, &pgErr) && pgErr.Code == "23505" {
305				return fail("reservation already exists")
306			}
307			return operationResult{}, err
308		}
309		resp.normalize()
310	
311		result := operationResult{status: http.StatusCreated, body: mustJSON(resp)}
312		if err := completeIdempotency(ctx, tx, tenantID, key, result); err != nil {
313			return operationResult{}, err
314		}
315		if err := tx.Commit(ctx); err != nil {
316			return operationResult{}, err
317		}
318		return result, nil
319	}
320	
321	func (s *pgStore) decideReservation(ctx context.Context, tenantID, poolID, reservationID, key, requestHash, decision string) (operationResult, error) {
322		tx, err := s.pool.Begin(ctx)
323		if err != nil {
324			return operationResult{}, err
325		}
326		defer tx.Rollback(ctx)
327	
328		operation := "decide_reservation:" + poolID + ":" + reservationID
329		outcome, replay, err := claimIdempotency(ctx, tx, tenantID, operation, key, requestHash)
330		if err != nil {
331			return operationResult{}, err
332		}
333		if outcome != idempotencyClaimed {
334			if err := tx.Commit(ctx); err != nil {
335				return operationResult{}, err
336			}
337			return replay, nil
338		}
339		fail := func(message string) (operationResult, error) {
340			return conflictResult(ctx, tx, tenantID, key, message)
341		}
342	
343		// Lock the pool first to serialize with reservation creation and with the
344		// opposite decision, so confirm and release cannot both take effect.
345		var poolLimit int64
346		err = tx.QueryRow(ctx, `
347			SELECT lim FROM quota_pools
348			WHERE tenant_id = $1 AND pool_id = $2
349			FOR UPDATE`,
350			tenantID, poolID,
351		).Scan(&poolLimit)
352		if errors.Is(err, pgx.ErrNoRows) {
353			return fail("reservation is not pending")
354		}
355		if err != nil {
356			return operationResult{}, err
357		}
358	
359		if err := expirePending(ctx, tx, tenantID, poolID); err != nil {
360			return operationResult{}, err
361		}
362	
363		var resp reservationResponse
364		err = tx.QueryRow(ctx, `
365			SELECT tenant_id, pool_id, reservation_id, amount, status, expires_at, created_at, updated_at
366			FROM reservations
367			WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3
368			FOR UPDATE`,
369			tenantID, poolID, reservationID,
370		).Scan(&resp.TenantID, &resp.PoolID, &resp.ReservationID, &resp.Amount, &resp.Status, &resp.ExpiresAt, &resp.CreatedAt, &resp.UpdatedAt)
371		if errors.Is(err, pgx.ErrNoRows) {
372			return fail("reservation is not pending")
373		}
374		if err != nil {
375			return operationResult{}, err
376		}
377		if resp.Status != "pending" {
378			return fail("reservation is not pending")
379		}
380	
381		err = tx.QueryRow(ctx, `
382			UPDATE reservations
383			SET status = $4, updated_at = now()
384			WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3
385			RETURNING updated_at`,
386			tenantID, poolID, reservationID, decision,
387		).Scan(&resp.UpdatedAt)
388		if err != nil {
389			return operationResult{}, err
390		}
391		resp.Status = decision
392		resp.normalize()
393	
394		result := operationResult{status: http.StatusOK, body: mustJSON(resp)}
395		if err := completeIdempotency(ctx, tx, tenantID, key, result); err != nil {
396			return operationResult{}, err
397		}
398		if err := tx.Commit(ctx); err != nil {
399			return operationResult{}, err
400		}
401		return result, nil
402	}
403	
404	func (s *pgStore) getReservation(ctx context.Context, tenantID, poolID, reservationID string) (reservationResponse, error) {
405		tx, err := s.pool.Begin(ctx)
406		if err != nil {
407			return reservationResponse{}, err
408		}
409		defer tx.Rollback(ctx)
410	
411		// Reflect lazy expiry on the fetched row.
412		if _, err := tx.Exec(ctx, `
413			UPDATE reservations
414			SET status = 'expired', updated_at = now()
415			WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3
416			  AND status = 'pending' AND expires_at <= now()`,
417			tenantID, poolID, reservationID); err != nil {
418			return reservationResponse{}, err
419		}
420	
421		var resp reservationResponse
422		err = tx.QueryRow(ctx, `
423			SELECT tenant_id, pool_id, reservation_id, amount, status, expires_at, created_at, updated_at
424			FROM reservations
425			WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3`,
426			tenantID, poolID, reservationID,
427		).Scan(&resp.TenantID, &resp.PoolID, &resp.ReservationID, &resp.Amount, &resp.Status, &resp.ExpiresAt, &resp.CreatedAt, &resp.UpdatedAt)
428		if errors.Is(err, pgx.ErrNoRows) {
429			return reservationResponse{}, errNotFound
430		}
431		if err != nil {
432			return reservationResponse{}, err
433		}
434		if err := tx.Commit(ctx); err != nil {
435			return reservationResponse{}, err
436		}
437		resp.normalize()
438		return resp, nil
439	}
