70	// Routing ---------------------------------------------------------------
71	
72	func New(b backend) http.Handler {
73		mux := http.NewServeMux()
74		api := &api{backend: b}
75	
76		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
77			respond(w, http.StatusOK, `{"status":"ok"}`)
78		})
79		mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
80			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
81			defer cancel()
82			if err := b.Ping(ctx); err != nil {
83				respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
84				return
85			}
86			respond(w, http.StatusOK, `{"status":"ready"}`)
87		})
88	
89		mux.HandleFunc("PUT /v1/tenants/{tenantId}/quota-pools/{poolId}", api.putPool)
90		mux.HandleFunc("POST /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations", api.postReservation)
91		mux.HandleFunc("POST /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations/{reservationId}/confirm", api.confirmReservation)
92		mux.HandleFunc("POST /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations/{reservationId}/release", api.releaseReservation)
93		// Alternate "R/{reservationId}:confirm|release" action syntax.
94		mux.HandleFunc("POST /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations/{idAction}", api.reservationAction)
95		mux.HandleFunc("GET /v1/tenants/{tenantId}/quota-pools/{poolId}/reservations/{reservationId}", api.getReservation)
96	
97		return mux
98	}
99	
100	type api struct {
101		backend backend
102	}
103	
104	// Request bodies --------------------------------------------------------
105	
106	type putPoolRequest struct {
107		Limit      *int64  `json:"limit"`
108		ValidFrom  *string `json:"validFrom"`
109		ValidUntil *string `json:"validUntil"`
110	}
111	
112	type postReservationRequest struct {
113		ReservationID *string `json:"reservationId"`
114		Amount        *int64  `json:"amount"`
115		ExpiresAt     *string `json:"expiresAt"`
116	}
117	
118	func decodeJSON(w http.ResponseWriter, r *http.Request, v any) bool {
119		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
120		dec := json.NewDecoder(r.Body)
121		dec.DisallowUnknownFields()
122		if err := dec.Decode(v); err != nil {
123			badRequest(w, "request body must be a valid JSON object")
124			return false
125		}
126		var extra json.RawMessage
127		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
128			badRequest(w, "request body must contain a single JSON object")
129			return false
130		}
131		return true
132	}
133	
134	func parseRFC3339(value *string) (time.Time, bool) {
135		if value == nil || strings.TrimSpace(*value) == "" {
136			return time.Time{}, false
137		}
138		parsed, err := time.Parse(time.RFC3339, strings.TrimSpace(*value))
139		if err != nil {
140			return time.Time{}, false
141		}
142		return parsed.UTC(), true
143	}
144	
145	func (a *api) idempotencyKey(w http.ResponseWriter, r *http.Request) (string, bool) {
146		key := strings.TrimSpace(r.Header.Get("Idempotency-Key"))
147		if key == "" {
148			badRequest(w, "Idempotency-Key header is required")
149			return "", false
150		}
151		return key, true
152	}
153	
154	func requestHash(r *http.Request, canonical []byte) string {
155		sum := sha256.Sum256([]byte(r.Method + "\n" + r.URL.Path + "\n" + string(canonical)))
156		return hex.EncodeToString(sum[:])
157	}
158	
159	// Handlers --------------------------------------------------------------
160	
161	func (a *api) putPool(w http.ResponseWriter, r *http.Request) {
162		tenantID := r.PathValue("tenantId")
163		poolID := r.PathValue("poolId")
164	
165		var req putPoolRequest
166		if !decodeJSON(w, r, &req) {
167			return
168		}
169		if req.Limit == nil || *req.Limit < 1 {
170			badRequest(w, "limit must be a positive integer")
171			return
172		}
173		validFrom, ok := parseRFC3339(req.ValidFrom)
174		if !ok {
175			badRequest(w, "validFrom must be an RFC3339 timestamp")
176			return
177		}
178		validUntil, ok := parseRFC3339(req.ValidUntil)
179		if !ok {
180			badRequest(w, "validUntil must be an RFC3339 timestamp")
181			return
182		}
183		if !validFrom.Before(validUntil) {
184			badRequest(w, "validFrom must be earlier than validUntil")
185			return
186		}
187	
188		pool, created, err := a.backend.createPool(r.Context(), tenantID, poolID, poolInput{
189			limit:      *req.Limit,
190			validFrom:  validFrom,
191			validUntil: validUntil,
192		})
193		if err != nil {
194			storageFailed(w, err)
195			return
196		}
197		if !created {
198			fail(w, http.StatusConflict, errorResponse{Error: "quota pool already exists"})
199			return
200		}
201		writeJSON(w, http.StatusCreated, pool)
202	}
203	
204	func (a *api) postReservation(w http.ResponseWriter, r *http.Request) {
205		key, ok := a.idempotencyKey(w, r)
206		if !ok {
207			return
208		}
209		tenantID := r.PathValue("tenantId")
210		poolID := r.PathValue("poolId")
211	
212		var req postReservationRequest
213		if !decodeJSON(w, r, &req) {
214			return
215		}
216		if req.ReservationID == nil || strings.TrimSpace(*req.ReservationID) == "" {
217			badRequest(w, "reservationId is required")
218			return
219		}
220		if req.Amount == nil || *req.Amount < 1 {
221			badRequest(w, "amount must be a positive integer")
222			return
223		}
224		expiresAt, ok := parseRFC3339(req.ExpiresAt)
225		if !ok {
226			badRequest(w, "expiresAt must be an RFC3339 timestamp")
227			return
228		}
229	
230		in := reservationInput{
231			reservationID: strings.TrimSpace(*req.ReservationID),
232			amount:        *req.Amount,
233			expiresAt:     expiresAt,
234		}
235		canonical, _ := json.Marshal(struct {
236			ReservationID string `json:"reservationId"`
237			Amount        int64  `json:"amount"`
238			ExpiresAt     string `json:"expiresAt"`
239		}{in.reservationID, in.amount, in.expiresAt.Format(time.RFC3339Nano)})
240	
241		result, err := a.backend.createReservation(r.Context(), tenantID, poolID, key, requestHash(r, canonical), in)
242		if err != nil {
243			storageFailed(w, err)
244			return
245		}
246		writeJSON(w, result.status, result.body)
247	}
248	
249	func (a *api) confirmReservation(w http.ResponseWriter, r *http.Request) {
250		a.decide(w, r, r.PathValue("reservationId"), "confirmed")
251	}
252	
253	func (a *api) releaseReservation(w http.ResponseWriter, r *http.Request) {
254		a.decide(w, r, r.PathValue("reservationId"), "released")
255	}
256	
257	func (a *api) reservationAction(w http.ResponseWriter, r *http.Request) {
258		// Accept the "R/{reservationId}:confirm" and ":release" action syntax.
259		tail := r.PathValue("idAction")
260		reservationID, action, ok := strings.Cut(tail, ":")
261		if !ok || reservationID == "" {
262			respond(w, http.StatusNotFound, `{"error":"not found"}`)
263			return
264		}
265		switch action {
266		case "confirm":
267			a.decide(w, r, reservationID, "confirmed")
268		case "release":
269			a.decide(w, r, reservationID, "released")
270		default:
271			respond(w, http.StatusNotFound, `{"error":"not found"}`)
272		}
273	}
274	
275	func (a *api) decide(w http.ResponseWriter, r *http.Request, reservationID, decision string) {
276		key, ok := a.idempotencyKey(w, r)
277		if !ok {
278			return
279		}
280		tenantID := r.PathValue("tenantId")
281		poolID := r.PathValue("poolId")
282		hash := requestHash(r, nil)
283	
284		result, err := a.backend.decideReservation(r.Context(), tenantID, poolID, reservationID, key, hash, decision)
285		if err != nil {
286			storageFailed(w, err)
287			return
288		}
289		writeJSON(w, result.status, result.body)
290	}
291	
292	func (a *api) getReservation(w http.ResponseWriter, r *http.Request) {
293		tenantID := r.PathValue("tenantId")
294		poolID := r.PathValue("poolId")
295		reservationID := r.PathValue("reservationId")
296	
297		reservation, err := a.backend.getReservation(r.Context(), tenantID, poolID, reservationID)
298		if err != nil {
299			if errors.Is(err, errNotFound) {
300				fail(w, http.StatusNotFound, errorResponse{Error: "reservation not found"})
301				return
302			}
303			storageFailed(w, err)
304			return
305		}
306		writeJSON(w, http.StatusOK, reservation)
307	}
308	
309	// Response helpers ------------------------------------------------------
310	
311	func badRequest(w http.ResponseWriter, message string) {
312		fail(w, http.StatusBadRequest, errorResponse{Error: message})
313	}
314	
315	func storageFailed(w http.ResponseWriter, err error) {
316		// Internal details go to the server log only, never to the client.
317		log.Printf("storage error: %v", err)
318		fail(w, http.StatusServiceUnavailable, errorResponse{Error: "service temporarily unavailable"})
319	}
320	
321	func fail(w http.ResponseWriter, status int, v any) {
322		writeJSON(w, status, v)
323	}
324	
325	func writeJSON(w http.ResponseWriter, status int, v any) {
326		var body []byte
327		switch b := v.(type) {
328		case []byte:
329			body = b
330		default:
331			encoded, err := json.Marshal(v)
332			if err != nil {
333				status = http.StatusServiceUnavailable
334				body = []byte(`{"error":"service temporarily unavailable"}`)
335				break
336			}
337			body = encoded
338		}
339		respond(w, status, string(body))
340	}
341	
342	func respond(w http.ResponseWriter, status int, body string) {
343		w.Header().Set("Content-Type", "application/json")
344		w.Header().Set("Cache-Control", "no-store")
345		w.WriteHeader(status)
346		_, _ = w.Write([]byte(body + "\n"))
347	}
