14	
15		"github.com/jackc/pgx/v5/pgxpool"
16	)
17	
18	func testDatabaseURL() string {
19		if url := os.Getenv("TEST_DATABASE_URL"); url != "" {
20			return url
21		}
22		return "postgres://127.0.0.1:15432/entitlements_test?sslmode=disable"
23	}
24	
25	type env struct {
26		t       *testing.T
27		pool    *pgxpool.Pool
28		handler http.Handler
29		seq     int
30	}
31	
32	func newEnv(t *testing.T) *env {
33		t.Helper()
34		pool, err := pgxpool.New(context.Background(), testDatabaseURL())
35		if err != nil {
36			t.Skipf("test database unavailable: %v", err)
37		}
38		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
39		defer cancel()
40		if err := pool.Ping(ctx); err != nil {
41			pool.Close()
42			t.Skipf("test database unreachable: %v", err)
43		}
44		// Recreate the schema so test runs track the current table definitions.
45		e := &env{t: t, pool: pool, handler: New(NewStore(pool))}
46		e.exec(`DROP TABLE IF EXISTS idempotency_records, reservations, quota_pools CASCADE`)
47		if err := EnsureSchema(ctx, pool); err != nil {
48			pool.Close()
49			t.Fatalf("ensure schema: %v", err)
50		}
51		t.Cleanup(pool.Close)
52		return e
53	}
54	
55	func (e *env) exec(sql string, args ...any) {
56		if _, err := e.pool.Exec(context.Background(), sql, args...); err != nil {
57			e.t.Fatalf("exec %q: %v", sql, err)
58		}
59	}
60	
61	func (e *env) queryInt(sql string, args ...any) int {
62		var n int
63		if err := e.pool.QueryRow(context.Background(), sql, args...).Scan(&n); err != nil {
64			e.t.Fatalf("query %q: %v", sql, err)
65		}
66		return n
67	}
68	
69	func (e *env) unique(base string) string {
70		e.seq++
71		return fmt.Sprintf("%s-%d", base, e.seq)
72	}
73	
74	// do issues a request through the full HTTP stack.
75	func (e *env) do(method, target, key, body string) *httptest.ResponseRecorder {
76		var r *http.Request
77		if body != "" {
78			r = httptest.NewRequest(method, target, strings.NewReader(body))
79		} else {
80			r = httptest.NewRequest(method, target, nil)
81		}
82		if key != "" {
83			r.Header.Set("Idempotency-Key", key)
84		}
85		rec := httptest.NewRecorder()
86		e.handler.ServeHTTP(rec, r)
87		return rec
88	}
89	
90	func (e *env) createPool(tenant, pool string, limit int, from, until time.Time) *httptest.ResponseRecorder {
91		body := fmt.Sprintf(`{"limit":%d,"validFrom":%q,"validUntil":%q}`,
92			limit, from.Format(time.RFC3339), until.Format(time.RFC3339))
93		return e.do(http.MethodPut, "/v1/tenants/"+tenant+"/quota-pools/"+pool, "", body)
94	}
95	
96	func (e *env) createReservationRaw(tenant, pool, key, body string) *httptest.ResponseRecorder {
97		return e.do(http.MethodPost, "/v1/tenants/"+tenant+"/quota-pools/"+pool+"/reservations", key, body)
98	}
99	
100	func (e *env) createReservation(tenant, pool, reservation, key string, amount int, expiresAt time.Time) *httptest.ResponseRecorder {
101		body := fmt.Sprintf(`{"reservationId":%q,"amount":%d,"expiresAt":%q}`,
102			reservation, amount, expiresAt.Format(time.RFC3339Nano))
103		return e.createReservationRaw(tenant, pool, key, body)
104	}
105	
106	func TestIntegrationPoolLifecycle(t *testing.T) {
107		e := newEnv(t)
108		now := time.Now().UTC()
109		rec := e.createPool("tA", "pA", 10, now.Add(-time.Hour), now.Add(time.Hour))
110		if rec.Code != http.StatusCreated {
111			t.Fatalf("create status=%d body=%s", rec.Code, rec.Body.String())
112		}
113		var created poolResponse
114		if err := json.Unmarshal(rec.Body.Bytes(), &created); err != nil {
115			t.Fatal(err)
116		}
117		if created.Limit != 10 || created.TenantID != "tA" {
118			t.Fatalf("unexpected payload %+v", created)
119		}
120	
121		rec = e.createPool("tA", "pA", 20, now.Add(-time.Hour), now.Add(time.Hour))
122		if rec.Code != http.StatusConflict {
123			t.Fatalf("duplicate pool status=%d", rec.Code)
124		}
125	}
126	
127	func TestIntegrationReservationHappyPathAndReplay(t *testing.T) {
128		e := newEnv(t)
129		now := time.Now().UTC()
130		e.createPool("t1", "p1", 10, now.Add(-time.Hour), now.Add(2*time.Hour))
131	
132		expiry := now.Add(time.Hour)
133		body := fmt.Sprintf(`{"reservationId":"r1","amount":4,"expiresAt":%q}`, expiry.Format(time.RFC3339Nano))
134	
135		first := e.createReservationRaw("t1", "p1", "key-1", body)
136		if first.Code != http.StatusCreated {
137			t.Fatalf("first status=%d body=%s", first.Code, first.Body.String())
138		}
139	
140		// Identical replay: 200 with the original result.
141		replay := e.createReservationRaw("t1", "p1", "key-1", body)
142		if replay.Code != http.StatusOK {
143			t.Fatalf("replay status=%d", replay.Code)
144		}
145		if replay.Body.String() != first.Body.String() {
146			t.Fatalf("replay body %s != original %s", replay.Body.String(), first.Body.String())
147		}
148		if e.queryInt(`SELECT count(*) FROM reservations WHERE tenant_id='t1' AND pool_id='p1'`) != 1 {
149			t.Fatal("replay must not create a second reservation")
150		}
151	
152		// Same key, different content: 409.
153		different := fmt.Sprintf(`{"reservationId":"r1","amount":5,"expiresAt":%q}`, expiry.Format(time.RFC3339Nano))
154		if rec := e.createReservationRaw("t1", "p1", "key-1", different); rec.Code != http.StatusConflict {
155			t.Fatalf("mismatch status=%d", rec.Code)
156		}
157	
158		// Same key under a different tenant is independent.
159		e.createPool("t2", "p1", 10, now.Add(-time.Hour), now.Add(2*time.Hour))
160		other := e.createReservationRaw("t2", "p1", "key-1", body)
161		if other.Code != http.StatusCreated {
162			t.Fatalf("cross-tenant same key status=%d body=%s", other.Code, other.Body.String())
163		}
164	}
