		t.Fatalf("unexpected allocation %+v", alloc)
	}

	// GET returns the same summary.
	rec = e.getAllocation("ta", "pa", "team-1")
	if rec.Code != http.StatusOK {
		t.Fatalf("get status=%d", rec.Code)
