535			strings.NewReader(`{"limit":1,"validFrom":"2026-01-01T00:00:00Z","validUntil":"2027-01-01T00:00:00Z"}`))
536		rec := httptest.NewRecorder()
537		h.ServeHTTP(rec, r)
