110		for _, tc := range []struct {
111			name, method, path, body string
112			dbError                  error
113			status                   int
114			calls                    int
115		}{
116			{"liveness", "GET", "/healthz", "ok", errors.New("database offline"), 200, 0},
117			{"ready", "GET", "/readyz", "ready", nil, 200, 1},
118			{"unavailable", "GET", "/readyz", "unavailable", errors.New("private connection details"), 503, 1},
119			{"unknown path", "GET", "/entitlements", "404", nil, 404, 0},
120			{"wrong method", "POST", "/readyz", "Method Not Allowed", nil, 405, 0},
121		} {
122			t.Run(tc.name, func(t *testing.T) {
123				calls := 0
124				mb := &mockBackend{pingErr: tc.dbError}
125				handler := New(&pingCountingBackend{mb, &calls})
126				response := httptest.NewRecorder()
127				handler.ServeHTTP(response, request(tc.method, tc.path, ""))
128				if response.Code != tc.status || !strings.Contains(response.Body.String(), tc.body) || calls != tc.calls {
129					t.Fatalf("status=%d body=%q database calls=%d", response.Code, response.Body.String(), calls)
130				}
131				if strings.Contains(response.Body.String(), "private connection details") {
132					t.Fatal("database error leaked into public response")
133				}
134			})
135		}
